import{_ as r,o as t,c as s,a8 as e}from"./chunks/framework.BWjTbCIc.js";const d=JSON.parse('{"title":"德望学校 · 2022/23资料年份 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-4b0457f5","school_zh":"德望学校","school_en":"—","grade":"s1","year":"2022-23","year_label":"2022/23资料年份","type":"interview","title":"德望学校 · 2022/23资料年份 · 中一 · 面试","anonymous":true,"source_ids":["C2223-GHS-FIRST","C2223-GHS-SECOND"],"rounds":["r1","r2"]},"headers":[],"relativePath":"reports/school-4b0457f5/s1/2022-23-interview.md","filePath":"reports/school-4b0457f5/s1/2022-23-interview.md"}'),p={name:"reports/school-4b0457f5/s1/2022-23-interview.md"};function n(a,o,c,g,l,i){return t(),s("div",null,[...o[0]||(o[0]=[e('<h1 id="德望学校-·-2022-23资料年份-·-中一-·-面试" tabindex="-1">德望学校 · 2022/23资料年份 · 中一 · 面试 <a class="header-anchor" href="#德望学校-·-2022-23资料年份-·-中一-·-面试" aria-label="Permalink to &quot;德望学校 · 2022/23资料年份 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-4b0457f5">← 返回德望学校资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c2223-ghs-first" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-ghs-first" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-ghs-first}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>分组与全程时间</strong></p><p>不同学生反馈全程约1.5至2小时，包含登记、核对身份、缴费或补交文件及等候。家长送达后按安排接回；语言环节有6至8人围成U形、两位老师主持的版本。以下按相近形式汇总，题目来自不同学生。</p></blockquote><blockquote><p><strong>语文：</strong> 普通话</p><p><strong>个人短讲</strong></p><p>约45秒至一分钟，题目包括难忘的网课及感受、最难忘的中文作业、印象深刻的同学、合作经历、学校活动的收获、喜欢的书和原因，以及疫情期间难忘的事。准备有即场回答、约1分半钟，或与小组任务合计准备3至3分半钟等版本。</p><p><strong>小组讨论</strong></p><p>6至8人讨论约5至7分钟。题目包括网课与面授比较、增设什么中文作业推广文化、设计关爱校园活动、专题研习能否提升合作、如何透过中一迎新加深对学校的认识、推广阅读会，以及帮助染疫同学。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>个人问答</strong></p><p>即场回答约30至45秒或一分钟，学生获派题目不同。涵盖与好友做什么、喜欢或想增设的校园设施、校服和服装、在家或餐厅用餐、老师、学科、KFC与McDonald’s、玩具、电视节目、电影、书和卡通。</p><p><strong>家庭、节日及学校生活</strong></p><p>喜欢的节日、若取消一个农历假期会选哪个、新年家庭活动；想不想有兄弟姐妹及其好处，或介绍现有兄弟姐妹；体育课、介绍自己的学校、是否想当老师及原因，以及想参加德望哪支运动队。</p><p><strong>朗读与即时填空</strong></p><p>读《蚂蚁与蚱蜢》、秃头男子与假发等寓言。另有约250词、三段文章的版本，一分钟准备、约一分钟朗读，读到两个空格时须即时填入正确动词形式。不同段落长短有差异。</p></blockquote><blockquote><p><strong>数学：</strong> 英语</p><p><strong>平板或电脑限时选择题</strong></p><p>常见反馈为10分钟约30至40题，多人记为35题，也有38题、四选一；另有约15道奥数题，或六页、每页约10题的回忆，题量并不一致。用iPad或电脑Google Forms作答，可跳题，部分需要心算。</p><p><strong>考点范围</strong></p><p>分数及带分数、速率、百分率、圆周率及圆周长、周界、四则运算、方程和逻辑解难，包含小学六年级知识及奥数式题目。</p></blockquote><h2 id="record-c2223-ghs-second" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-ghs-second" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-ghs-second}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong> 学生多用英语，家长多用粤语；亦有全英语版本</p><p><strong>学生与家长面谈</strong></p><p>由两位老师，或校长与副校长主持。题目按学生经历及回答追问，不是每位考生都回答以下全部问题。</p></blockquote><blockquote><p><strong>学生面谈：</strong> 英语为主</p><p><strong>学习与阅读</strong></p><p>难忘的学校经历、喜欢学校什么、学习强弱项、最喜欢和最不喜欢的学科；介绍中英文书籍、数学是否困难，以及曾获得的奖项。</p><p><strong>活动、领导与时间分配</strong></p><p>田径或辩论学到什么；为何游泳、多久练习一次、怎样兼顾学习；幼女童军经历；繁忙周末如何安排家庭活动；领袖生与队长的职责及困难；演戏机会、老师对自己的评价，以及多项活动间如何选择。</p><p><strong>择校与开放问题</strong></p><p>为何选择德望、还申请了哪些学校；若有魔法棒会变成什么动物；Hope、Joy、Thanksgiving、Love之中哪个最重要，为什么。</p></blockquote><blockquote><p><strong>家长面谈：</strong> 粤语为主，部分英语</p><p><strong>择校与适应</strong></p><p>择校原因及考虑因素、对孩子升中一的期望、其他录取选择、通勤距离、是否全家支持择校决定；若小学设有直属中学，为什么仍选择转校、如何帮助适应。</p><p><strong>家庭支持</strong></p><p>孩子的优点与待改进之处、平日及周末生活、能否独立学习、如何配合学习、支持课外活动和家校合作，以及家庭如何安排时间。</p></blockquote>',20)])])}const u=r(p,[["render",n]]);export{d as __pageData,u as default};
